 test('el catálogo local mantiene perfiles completos y bibliografía seleccionada', () => {
   assert.equal(AUTORES_27.length, 14);
   assert.ok(AUTORES_27.reduce((total, autor) => total + autor.obras.length, 0) >= 70);
